  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Peter W. Shor",
        "Andrew M. Steane",
        "Alexei Kitaev"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected against noise, turning fragile quantum states into a physically meaningful and testable resource. Its conceptual importance reaches beyond computing to the foundations of quantum measurement and control.",
        "attribution": "Shor and Steane established influential early codes; Kitaev developed the topological approach and fault-tolerant framework. Their contributions are distinct and collectively capture the field's central breakthroughs.",
        "maturity": "The principles have been experimentally demonstrated and developed across multiple platforms over decades. The long path from codes to increasingly capable error-corrected systems confirms lasting significance.",
        "uncertainties": [
          "The breadth of the field makes a three-person attribution necessarily selective."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattices made controlled many-body quantum systems experimentally accessible, including regimes that are difficult to calculate directly. This is a fundamental advance in quantum physics and a powerful bridge between theory and experiment.",
        "attribution": "Bloch and Greiner led landmark experimental demonstrations; Zoller helped establish the theoretical vision for quantum simulation with cold atoms. Cirac also made major theoretical contributions, making the boundary of a three-person prize difficult.",
        "maturity": "The platform has produced robust, reproducible results and continued to advance for many years. Its scientific impact is established even as new regimes remain under exploration.",
        "uncertainties": [
          "The discovery is a broad program whose key conceptual and experimental contributions are spread across several groups."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed atomic timekeeping by enabling exceptionally precise measurements with many trapped atoms while controlling key systematic effects. They open a route to tests of fundamental physics through precision measurement.",
        "attribution": "Katori introduced the magic-wavelength lattice clock concept, and Ye's group made major experimental advances in clock performance and applications. The credited pairing reflects complementary foundational contributions.",
        "maturity": "Independent implementations and sustained improvements establish the method as a mature precision tool. Its broader fundamental applications continue to develop.",
        "uncertainties": [
          "The relative weight of the original concept and subsequent experimental realization may be judged differently."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Rainer Blatt",
        "Juan Ignacio Cirac",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions provided a clear, controllable route to quantum logic and entanglement, making the quantum information program experimentally concrete. The work also deepened understanding of coherent control in small quantum systems.",
        "attribution": "Cirac and Zoller developed the influential ion-trap gate proposal; Blatt's experiments demonstrated and advanced the method. The theory–experiment pairing is compelling, though other experimental groups were also essential.",
        "maturity": "The approach has been reproduced and scaled over decades, with demonstrations of increasingly capable processors. Its fundamental contribution is secure even as practical scaling remains challenging.",
        "uncertainties": [
          "The candidate overlaps substantially with broader quantum computing and atomic quantum information achievements."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Jun Ye",
        "John M. Doyle",
        "David DeMille"
      ],
      "assessment": {
        "nobel_worthiness": "The production and control of ultracold molecules opened a new domain of quantum matter with rich internal structure, long-range interactions and prospects for precision tests. This is a substantial experimental achievement with fundamental reach.",
        "attribution": "Ye, Doyle and DeMille represent complementary advances in molecular cooling, trapping and control. The field's development involved multiple techniques and groups, so assigning the central credit is not straightforward.",
        "maturity": "The experimental toolkit is now established and the field has grown substantially. Some of its most distinctive scientific opportunities are still being realized.",
        "uncertainties": [
          "The field is broad, and the candidate list may not capture all contributors to its experimental foundations."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Claudio Pellegrini",
        "Jörg Rossbach",
        "Kwang-Je Kim"
      ],
      "assessment": {
        "nobel_worthiness": "X-ray free-electron lasers created intense, ultrashort coherent pulses at wavelengths that reveal atomic-scale structure and dynamics. This is a major advance in experimental access to matter, with fundamental discoveries enabled by the new source.",
        "attribution": "Pellegrini's concepts and accelerator physics, Kim's undulator and FEL theory, and Rossbach's work on implementation represent important parts of the development. The international, facility-scale history complicates individual attribution.",
        "maturity": "Multiple facilities and research communities have established the technology and its scientific value. The source has supported a sustained body of results.",
        "uncertainties": [
          "Credit for a large-scale instrument is distributed across many scientists and institutions."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals showed how periodic structures can control light propagation and inhibit or shape optical modes. This is a fundamental and influential idea at the boundary of wave physics and materials science.",
        "attribution": "Yablonovitch and John independently introduced central photonic band-gap ideas, while Joannopoulos helped develop the theory and bring the field to broad use. The credited trio reflects distinct contributions.",
        "maturity": "The concept has been confirmed in many structures and has supported a wide range of optical research. Its intellectual influence is established.",
        "uncertainties": [
          "The separate independent origins and the later expansion of the field make a single discovery boundary difficult to define."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Toshiki Tajima",
        "Wim Leemans",
        "Victor Malka"
      ],
      "assessment": {
        "nobel_worthiness": "Laser-plasma wakefield acceleration offers a striking way to generate high-energy particle beams over much shorter distances than conventional accelerators. The underlying plasma physics is important and potentially transformative.",
        "attribution": "Tajima and Dawson introduced the seminal acceleration concept; Leemans and Malka led major experimental demonstrations and advances. The credited names span theory and experimental realization.",
        "maturity": "The mechanism has been demonstrated repeatedly, but beam quality, stability and reliable operation remain active challenges. The full scientific and practical significance is still emerging.",
        "uncertainties": [
          "The distance between proof of principle and a broadly established accelerator capability remains substantial."
        ]
      }
    }
  ]
